def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A full-color line separates repeated regions. The final region is the
    # template; copy its non-background marks into each preceding region.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    if sep_rows:
        color = grid[sep_rows[0]][0]
        bounds = [-1] + sep_rows + [h]
        regions = [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]
        sr, se = regions[-1]
        for a, b in regions[:-1]:
            for r in range(min(b - a, se - sr)):
                for c in range(w):
                    v = grid[sr + r][c]
                    if v != 2 and v != color:
                        out[a + r][c] = v

    if sep_cols:
        color = grid[0][sep_cols[0]]
        bounds = [-1] + sep_cols + [w]
        regions = [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]
        sc, se = regions[-1]
